import{_t as e,it as t,n,rt as r}from"./chunks/framework.DD2lXFOM.js";var i=JSON.parse(`{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction/index.md","filePath":"guide/introduction/index.md"}`),a={name:`guide/introduction/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h1><p>GraphVis 是一个基于 <a href="https://pixijs.com/" target="_blank" rel="noreferrer">PixiJS</a> 的图可视化库，专注于高性能的图数据渲染与交互。它支持上万节点与边的流畅绘制，适用于需要展示复杂关系网络的场景，如社交网络分析、知识图谱、拓扑结构、流程图等。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to “核心特性”">​</a></h2><ul><li><strong>高性能渲染</strong>：基于 PixiJS 的 WebGL 渲染管线，轻松支撑上万节点与边的实时交互。</li><li><strong>多种图类型</strong>：支持有向图、无向图与混合图，满足不同关系表达需求。</li><li><strong>丰富的节点与边</strong>：内置圆形、椭圆、矩形、多边形、星形、文本、图片等多种节点类型，以及直线、曲线、自动边等边类型。</li><li><strong>灵活的布局</strong>：集成 <code>d3-force</code>、<code>random</code> 等布局，并支持自定义扩展。</li><li><strong>完整的交互事件</strong>：提供节点、边、Stage 的指针、鼠标、触摸、拖拽等事件监听，方便实现选中、悬停、连线等交互。</li><li><strong>主题与样式</strong>：支持动态切换主题，也可根据主题色自动生成配色方案。</li><li><strong>可扩展架构</strong>：通过 <code>register</code> 方法注册自定义节点、边、布局与主题，轻松扩展库的能力。</li></ul>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};